[{"id": "a7a1149", "elType": "container", "settings": {"flex_direction": "column", "content_width": "full", "padding": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": true}, "margin": {"unit": "px", "top": "0", "right": "0", "bottom": "0", "left": "0", "isLinked": true}, "flex_gap": {"column": "0", "row": "0", "isLinked": true, "unit": "px"}, "css_classes": "syx-root"}, "elements": [{"id": "012d0ea", "elType": "widget", "settings": {"html": "<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Heebo:wght@300;400;500;700;800;900&display=swap" rel="stylesheet"><style>
html{scroll-behavior:smooth;scroll-padding-top:96px}
body{background:#060b16;direction:rtl;margin:0;overscroll-behavior-y:none}
.syx{--gold:#EBC66C;--gold2:#F4D275;--goldg:linear-gradient(135deg,#E0B05A 0%,#F4D275 50%,#E4B85E 100%);--bronze:#C5965D;--soft:#fff;--soft2:#fff;--navy:#060b16;--navy2:#0a1428;--navy3:#0e1c38;--blue:#3fa4ff;--cream:#F6F1E6;--ink:#000;--text:#fff;--mute:#fff;--line:rgba(235,198,108,.38);
 --out:cubic-bezier(.23,1,.32,1);
 font-family:"Heebo",system-ui,sans-serif;color:var(--text);direction:rtl;text-align:right;line-height:1.6;
 -webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale;overflow-x:clip;position:relative;isolation:isolate}
.syx *,.syx *::before,.syx *::after{box-sizing:border-box}
/* the WordPress theme colours every heading blue; headings must follow the section they sit in (white on dark, black on light) */
.syx h1,.syx h2,.syx h3,.syx h4,.syx h5,.syx h6{color:inherit}
.syx h1,.syx h2,.syx h3,.syx p{margin:0}
.syx img{display:block;max-width:100%}
.syx a{color:inherit;text-decoration:none}
.syx :focus-visible{outline:2px solid var(--gold2);outline-offset:3px;border-radius:10px}
.syx .wrap{width:min(1180px,100% - 40px);margin-inline:auto}
.syx h1,.syx h2,.syx h3{text-wrap:balance}.syx p{text-wrap:pretty}
.syx .gold{background:var(--goldg);background-size:220% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:syxShine 7s linear infinite}
@keyframes syxShine{0%{background-position:0 0}100%{background-position:-220% 0}}
.syx h2.t{font-size:clamp(28px,3.6vw,44px);line-height:1.15;font-weight:900;letter-spacing:-.02em;text-align:center;margin-bottom:34px}

/* progress + header pill */
.syx-progress{position:fixed;inset:0 0 auto 0;height:3px;z-index:1002;pointer-events:none}
.syx-progress i{display:block;height:100%;width:100%;background:var(--goldg);transform-origin:100% 50%;transform:scaleX(0);box-shadow:0 0 14px rgba(235,198,108,.8)}
.syx-head{position:fixed;inset:14px 0 auto 0;z-index:1001;transition:transform .45s var(--out)}
.syx-head.is-hidden{transform:translateY(-130%)}
.syx-head .pill{width:min(1180px,100% - 28px);margin-inline:auto;height:64px;padding:0 22px;display:flex;align-items:center;justify-content:space-between;gap:18px;border-radius:20px;border:1px solid rgba(120,170,255,.28);background:rgba(8,16,34,.55);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);box-shadow:0 10px 40px rgba(0,0,0,.35),inset 0 1px 0 rgba(255,255,255,.06);transition:background-color .3s ease,border-color .3s ease}
.syx-head.is-solid .pill{background:rgba(6,11,22,.88);border-color:var(--line)}
.syx-logo img{height:40px;width:auto}
.syx-head .btn{white-space:nowrap}
.syx-head .m{display:none}
@media (max-width:560px){.syx-head .d{display:none}.syx-head .m{display:inline}}
.syx-nav{display:flex;align-items:center}
.syx-nav a{position:relative;padding:10px 20px;font-size:15px;font-weight:500;color:#fff;transition:color .2s ease}
.syx-nav a+a::before{content:"";position:absolute;right:0;top:50%;width:1px;height:16px;margin-top:-8px;background:rgba(255,255,255,.2)}
.syx-nav a.is-on{color:var(--gold2)}
@media (hover:hover) and (pointer:fine){.syx-nav a:hover{color:var(--gold2)}}

/* buttons */
.syx .btn{--bx:0px;--by:0px;position:relative;display:inline-flex;align-items:center;justify-content:center;gap:10px;min-height:52px;padding:0 30px;border-radius:999px;font:800 17px/1 "Heebo",sans-serif;border:1.5px solid var(--gold);cursor:pointer;color:var(--text);
 transform:translate(var(--bx),var(--by));transition:transform .35s var(--out),box-shadow .3s ease,background-color .2s ease;overflow:hidden;isolation:isolate}
.syx .btn:active{transform:translate(var(--bx),var(--by)) scale(.97)}
.syx .btn svg{width:18px;height:18px;flex:none;transition:transform .35s var(--out)}
.syx .btn-gold{background:var(--goldg);color:#1a1405;border-color:transparent;box-shadow:0 8px 28px rgba(235,198,108,.32),inset 0 1px 0 rgba(255,255,255,.5)}
.syx .btn-gold::after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(105deg,transparent 30%,rgba(255,255,255,.65) 50%,transparent 70%);transform:translateX(120%);transition:transform .8s var(--out)}
.syx .btn-ghost{background:rgba(8,16,34,.4);color:var(--gold2);backdrop-filter:blur(6px)}
.syx .btn-sm{min-height:44px;padding:0 22px;font-size:15px}
@media (hover:hover) and (pointer:fine){
 .syx .btn-gold:hover{box-shadow:0 14px 42px rgba(235,198,108,.5),inset 0 1px 0 rgba(255,255,255,.6)}
 .syx .btn-gold:hover::after{transform:translateX(-120%)}
 .syx .btn:hover svg{transform:translateX(-5px)}
 .syx .btn-ghost:hover{background:rgba(235,198,108,.14)}
}

/* shared dark backdrop */
.syx .dark{position:relative;background:linear-gradient(180deg,rgba(6,11,22,.35),rgba(6,11,22,.1) 40%,rgba(6,11,22,.55)),url(https://nivcreative.com/wp-content/uploads/2026/10/syx-bg-glow.webp) center/cover no-repeat,var(--navy);padding:clamp(54px,7vw,84px) 0}
.syx .cream{background:linear-gradient(180deg,#fbf8f0,var(--cream));color:var(--ink);padding:clamp(54px,7vw,84px) 0}
.syx .cream p{color:#000}

/* hero */
.syx-hero{position:relative;min-height:min(100svh,860px);display:flex;align-items:center;padding:130px 0 80px;overflow:hidden;background:#050912}
.syx-hero .bg{position:absolute;inset:-5% -2%;background:url(https://nivcreative.com/wp-content/uploads/2026/10/shay-hero-stage.webp) 18% 12%/cover no-repeat;will-change:transform;transform:translate3d(var(--px,0),var(--py,0),0) scale(1.06)}
.syx-hero::before{content:"";position:absolute;inset:0;z-index:1;background:radial-gradient(700px 500px at 80% 40%,rgba(14,40,90,.55),transparent 70%),linear-gradient(270deg,rgba(5,9,18,.94) 6%,rgba(5,9,18,.62) 40%,rgba(5,9,18,.05) 72%),linear-gradient(0deg,var(--navy2) 0,transparent 20%),linear-gradient(180deg,rgba(5,9,18,.5),transparent 25%)}
.syx-hero .sheen{position:absolute;inset:0;z-index:2;overflow:hidden;pointer-events:none}
.syx-hero .sheen::after{content:"";position:absolute;inset:-10% 0;width:60%;background:linear-gradient(115deg,transparent 30%,rgba(255,255,255,.2) 50%,transparent 70%);transform:translateX(280%) skewX(-12deg);animation:syxSheen 9s cubic-bezier(.4,0,.4,1) infinite 1.2s;will-change:transform}
@keyframes syxSheen{0%{transform:translateX(280%) skewX(-12deg)}60%,100%{transform:translateX(-120%) skewX(-12deg)}}
.syx-hero .spot{position:absolute;z-index:2;width:560px;height:560px;left:0;top:0;margin:-280px 0 0 -280px;border-radius:50%;background:radial-gradient(circle,rgba(255,215,130,.2),transparent 62%);mix-blend-mode:screen;pointer-events:none;transform:translate3d(var(--sx,50vw),var(--sy,40vh),0);will-change:transform;opacity:0;transition:opacity .6s ease}
.syx-hero.is-live .spot{opacity:1}
.syx-hero canvas{position:absolute;inset:0;z-index:2;width:100%;height:100%;pointer-events:none}
.syx-hero .wrap{position:relative;z-index:3}
.syx-hero .copy{max-width:720px}
@media (min-width:561px){.syx-hero h1 .ln:last-child .w{white-space:nowrap}}
.syx-hero .tag{display:block;font-size:clamp(14px,1.4vw,17px);font-weight:500;color:#fff;margin-bottom:14px}
.syx-hero .tag b{font-weight:800}
.syx-hero .tag i{display:inline-block;width:1px;height:1em;background:rgba(255,255,255,.55);margin:0 10px;vertical-align:-.15em}
.syx-hero h1{font-size:clamp(38px,5.4vw,72px);line-height:1.06;font-weight:900;letter-spacing:-.03em}
.syx-hero h1 .ln{display:block}
.syx-hero h1 .w{display:inline-block;max-width:100%;overflow:hidden;vertical-align:top;padding-bottom:.14em;margin-bottom:-.14em}
.syx-hero h1 .w>span{display:inline-block}
.syx-hero .lead{margin-top:22px;font-size:clamp(17px,1.8vw,23px);font-weight:300;line-height:1.55;color:#fff;max-width:520px}
.syx .cta-row{display:flex;flex-wrap:wrap;gap:14px;margin-top:34px}
.syx .cta-row .btn svg.pl{width:26px;height:26px}

/* what to advance */
.syx .cards{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;perspective:1100px}
.syx .card{--rx:0deg;--ry:0deg;--gx:50%;--gy:50%;position:relative;display:flex;flex-direction:column;justify-content:flex-end;min-height:420px;border-radius:18px;overflow:hidden;background:#0a1428;border:1px solid var(--line);
 transform:rotateX(var(--rx)) rotateY(var(--ry));transform-style:preserve-3d;transition:transform .5s var(--out),box-shadow .4s ease,border-color .3s ease;will-change:transform}
.syx .card .im{position:absolute;inset:0;background-size:cover;background-position:center;transition:transform .9s var(--out)}
.syx .card::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(0deg,rgba(6,12,28,.96) 14%,rgba(6,12,28,.35) 62%,rgba(20,60,130,.25))}
.syx .card::after{content:"";position:absolute;inset:0;z-index:2;pointer-events:none;opacity:0;transition:opacity .3s ease;background:radial-gradient(260px circle at var(--gx) var(--gy),rgba(255,226,160,.25),transparent 70%)}
.syx .card .body{position:relative;z-index:3;padding:22px 20px;display:grid;gap:12px;text-align:center;justify-items:center}
.syx .card h3{font-size:23px;font-weight:800;line-height:1.2}
.syx .card .desc{font-size:15.5px;font-weight:300;line-height:1.5;color:#fff;min-height:46px}
.syx .card .more{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;min-height:46px;margin-top:6px;border:1.5px solid var(--gold);border-radius:999px;background:rgba(8,16,34,.5);color:var(--gold2);font-weight:700;font-size:15px;transition:background-color .25s ease}
.syx .card .more svg{width:16px;height:16px;transition:transform .35s var(--out)}
@media (hover:hover) and (pointer:fine){
 .syx .card:hover .more{background:rgba(235,198,108,.2)}
 .syx .card{transition:transform .12s linear,box-shadow .4s ease,border-color .3s ease}
 .syx .card:hover{border-color:var(--gold);box-shadow:0 26px 60px rgba(0,0,0,.6),0 0 40px rgba(63,164,255,.2)}
 .syx .card:hover .im{transform:scale(1.08)}.syx .card:hover::after{opacity:1}
 .syx .card:hover .more svg{transform:translateX(-5px)}
}

/* about (cream) */
.syx-about .grid{display:grid;grid-template-columns:1fr 1fr;gap:clamp(28px,5vw,64px);align-items:center}
.syx .linkline{display:inline-flex;align-items:center;gap:8px;min-height:44px;font-weight:700;color:#000;border-bottom:2px solid #C5965D;transition:gap .3s var(--out)}
.syx .linkline svg{width:16px;height:16px;color:#C5965D}
@media (hover:hover) and (pointer:fine){.syx .linkline:hover{gap:14px}}
.syx-about h2{font-size:clamp(30px,4vw,48px);font-weight:900;line-height:1.1;margin-bottom:14px;letter-spacing:-.02em}
.syx-about .copy>p{font-size:19px;max-width:440px;font-weight:400;color:#000}
.syx .feats{display:grid;grid-template-columns:repeat(3,1fr);margin-top:6px;margin-bottom:10px}
.syx .feat{display:grid;justify-items:center;align-content:start;gap:8px;padding:6px 14px;text-align:center}
.syx .feat+.feat{border-right:1px solid rgba(18,21,28,.14)}
.syx .feat svg{width:52px;height:52px;overflow:visible}
.syx .feat .num{font-size:22px;font-weight:900;color:#C5965D;font-variant-numeric:tabular-nums;letter-spacing:.04em}
.syx .feat b{font-size:20px;font-weight:800;line-height:1.1}
.syx .feat span:last-child{font-size:15px;font-weight:400;color:#000;max-width:190px;line-height:1.45}
.syx .ico path,.syx .ico circle,.syx .ico rect,.syx .ico line{fill:none;stroke:#C5965D;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.syx-js .ico *{stroke-dasharray:1;stroke-dashoffset:1;transition:stroke-dashoffset 1.4s var(--out);transition-delay:calc(var(--i,0) * 120ms + .3s)}
.syx-js .in .ico *,.syx-js .ico.in *{stroke-dashoffset:0}
.syx .vbox{position:relative;aspect-ratio:16/10;border-radius:18px;overflow:hidden;background:#000;border:1px solid rgba(18,21,28,.18);box-shadow:0 24px 60px rgba(18,21,28,.28),0 0 0 6px rgba(255,255,255,.7)}
.syx .media{position:absolute;inset:0;background-size:cover;background-position:center;transition:transform 1s var(--out)}
.syx .vbox::after,.syx .vcard::after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.4),transparent 55%);pointer-events:none}
.syx .play{position:absolute;z-index:3;inset:0;margin:auto;width:76px;height:76px;border-radius:50%;border:2px solid #fff;background:rgba(10,18,36,.55);backdrop-filter:blur(6px);display:grid;place-items:center;cursor:pointer;padding:0;animation:syxPulse 2.6s var(--out) infinite;transition:transform .35s var(--out)}
.syx .play svg{width:28px;height:28px;fill:#fff;margin-left:-3px}
.syx .play:active{transform:scale(.94)}
@keyframes syxPulse{0%{box-shadow:0 0 0 0 rgba(255,255,255,.4)}70%,100%{box-shadow:0 0 0 22px rgba(255,255,255,0)}}
@media (hover:hover) and (pointer:fine){.syx .play:hover{transform:scale(1.1)}.syx .vbox:hover .media,.syx .vcard:hover .media{transform:scale(1.05)}}
.syx .vbox iframe,.syx .vcard iframe{position:absolute;inset:0;z-index:4;width:100%;height:100%;border:0}

/* start with intro videos */
.syx .vids{display:grid;grid-template-columns:1fr 1fr;gap:20px}
.syx .vcard{position:relative;min-height:290px;border-radius:18px;overflow:hidden;border:1px solid var(--line);background:#000;isolation:isolate;display:flex;align-items:flex-end}
.syx .vcard::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(270deg,rgba(6,12,28,.9),rgba(6,12,28,.3) 70%)}
.syx .vcard .vin{position:relative;z-index:3;display:grid;gap:14px;justify-items:start;padding:26px;max-width:62%}
.syx .vcard h3{font-size:clamp(24px,2.6vw,32px);font-weight:800;line-height:1.15}
.syx .vcard .play{inset:auto;position:relative;margin:0;width:56px;height:56px}
.syx .vcard .play svg{width:20px;height:20px}
.syx .vcard .row{display:flex;align-items:center;gap:14px;flex-wrap:wrap}

/* team */
.syx .team{display:grid;grid-template-columns:repeat(3,minmax(0,250px));gap:clamp(18px,4vw,56px);justify-content:center}
.syx .member{text-align:center;font-weight:600;font-size:17px;color:#000}
.syx .member .ph{position:relative;aspect-ratio:1.12;border-radius:10px;overflow:hidden;margin-bottom:10px;background:radial-gradient(120% 90% at 70% 10%,#33557f,#0c1830 60%);box-shadow:0 14px 30px rgba(18,21,28,.28);transition:transform .5s var(--out)}
.syx .member .ph svg{position:absolute;inset:0;width:100%;height:100%}
.syx .member .ph::after{content:"";position:absolute;inset:auto 0 0 0;height:36%;background:linear-gradient(0deg,rgba(235,198,108,.28),transparent)}
@media (hover:hover) and (pointer:fine){.syx .member:hover .ph{transform:translateY(-6px)}}
.syx .center{display:flex;justify-content:center;margin-top:30px}
.syx .cream .btn-ghost{background:transparent;color:#000;border-color:#C5965D}
@media (hover:hover) and (pointer:fine){.syx .cream .btn-ghost:hover{background:rgba(196,138,28,.12)}}

/* 1:1 banner */
.syx-one{position:relative;display:grid;grid-template-columns:.8fr 1.4fr;min-height:300px;background:#071022;overflow:hidden}
.syx-one .txt{position:relative;z-index:2;display:grid;align-content:center;gap:10px;padding:34px clamp(22px,6vw,90px) 34px 30px;background:linear-gradient(270deg,#071022 70%,transparent)}
.syx-one h2{font-size:clamp(30px,3.6vw,46px);line-height:1.1;font-weight:900;letter-spacing:-.02em}
.syx-one p{font-size:18px;color:var(--soft)}
.syx-one .price{font-size:clamp(20px,2vw,24px);font-weight:800;font-variant-numeric:tabular-nums}
.syx-one .price b{font-size:1.25em;color:var(--gold2)}
.syx-one .txt .btn{justify-self:start;margin-top:8px}
.syx-one .pic{position:relative;overflow:hidden}
.syx-one .pic .im{position:absolute;inset:-6% 0;background:url(https://nivcreative.com/wp-content/uploads/2026/10/syx-card-1to1.webp) center 58%/cover;will-change:transform;transform:translate3d(0,var(--ty,0),0) scale(1.04)}
.syx-one .pic::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(7,16,34,.95),transparent 55%),linear-gradient(0deg,rgba(14,50,110,.35),transparent)}

/* partners */
.syx-part{background:linear-gradient(90deg,rgba(6,11,22,.1),rgba(6,11,22,.45)),url(https://nivcreative.com/wp-content/uploads/2026/10/syx-bg-band.webp) left center/cover no-repeat,var(--navy2);border-block:1px solid rgba(120,170,255,.14);padding:46px 0}
.syx-part .wrap{display:grid;grid-template-columns:1.2fr auto;gap:30px;align-items:center}
.syx-part .t2{font-size:clamp(28px,3.2vw,40px);font-weight:900;line-height:1.15}
.syx-part p{font-size:18px;color:#fff;margin:6px 0 18px}
.syx-part .ppl{display:flex;align-items:center;gap:36px;justify-self:center;margin-inline:auto}
.syx-part .ppl::before{content:"";width:1px;height:72px;background:rgba(255,255,255,.22)}
.syx-part .ppl svg{width:92px;height:92px;overflow:visible}
.syx-part .ico *{stroke:var(--gold)}

/* faq (cream) */
.syx-faq .list{display:grid;gap:12px;max-width:900px;margin-inline:auto}
.syx details{border:1px solid rgba(18,21,28,.2);border-radius:10px;background:rgba(255,255,255,.6);transition:border-color .3s ease,background-color .3s ease,box-shadow .3s ease}
.syx details[open]{border-color:#C5965D;background:#fff;box-shadow:0 12px 30px rgba(18,21,28,.1)}
.syx summary{list-style:none;cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:60px;padding:12px 22px;font-size:clamp(16px,1.6vw,19px);font-weight:700;color:var(--ink)}
.syx summary::-webkit-details-marker{display:none}
.syx summary i{position:relative;flex:none;width:28px;height:28px;border-radius:50%;border:1.5px solid var(--ink)}
.syx summary i::before,.syx summary i::after{content:"";position:absolute;inset:0;margin:auto;width:11px;height:2px;background:var(--ink);transition:transform .35s var(--out)}
.syx summary i::after{transform:rotate(90deg)}
.syx details[open] summary i::after{transform:rotate(0)}
.syx details .ans{padding:0 22px 20px;font-size:17px;color:#000;animation:syxPane .5s var(--out) both}
@keyframes syxPane{from{opacity:0;transform:translateY(10px);filter:blur(5px)}to{opacity:1;transform:none;filter:none}}

/* contact */
.syx-contact{position:relative;text-align:center;padding:clamp(54px,7vw,84px) 0 0;background:linear-gradient(180deg,transparent 55%,#050d1c),url(https://nivcreative.com/wp-content/uploads/2026/10/syx-bg-stage.webp) center top/cover no-repeat,#050d1c;padding-bottom:12px}
.syx-contact .wrap{position:relative}
.syx-contact h2.t{margin-bottom:0}
.syx-formcont{background:linear-gradient(180deg,#050d1c,transparent 45%),url(https://nivcreative.com/wp-content/uploads/2026/10/syx-bg-stage.webp) center bottom/cover no-repeat,#050d1c;padding:30px 0 clamp(54px,7vw,84px)}
.syx-formwrap{width:min(940px,100% - 40px);margin-inline:auto}
.syx-formwrap .elementor-field-textual{min-height:52px;color:#fff}
.syx-formwrap .elementor-field-textual::placeholder{color:#fff;opacity:1}
.syx-formwrap select.elementor-field-textual option{color:#000}
.syx-formwrap .elementor-field-type-submit{justify-content:center}
.syx-formwrap .elementor-button{min-height:54px;min-width:260px}

/* footer */
.syx-foot{padding:34px 0;background:#050a14;border-top:1px solid rgba(255,255,255,.07)}
.syx-foot .wrap{display:flex;flex-wrap:wrap;gap:24px;align-items:flex-start;justify-content:space-between}
.syx-foot img{height:44px;width:auto}
.syx-foot nav{display:flex;flex-wrap:wrap;gap:0 2px}
.syx-foot nav a{position:relative;padding:10px 16px;font-size:15px;color:#fff;transition:color .2s ease}
